      "Hòe (còn gọi Lài luồng, Hòe hoa, Hòe mễ) là cây nhỡ thuộc họ Đậu thường xanh cao 5-7m, có khi đến 10m. Thân có vỏ hơi nứt nẻ và cành nằm ngang. Cành hình trụ nhẵn màu xanh lục nhạt có những chấm trắng. Lá kép lông chim lẻ mọc so le, 11-17 lá chét mọc đối hình bầu dục-thuôn, gốc tròn đầu hơi nhọn dài 3-4cm rộng 1,2-2cm màu lục nhạt nhất là ở mặt dưới hơi có lông. Cụm hoa mọc ở đầu cành thành chùm dài 20cm phân nhánh nhiều, hoa nhỏ màu trắng hoặc vàng nhạt, đài hình chuông gần như nhẵn, cánh hoa có móng ngắn cánh cờ rộng hình tim cụt ở gốc mép cong lên, nhị 10 rời nhau, bao phấn hình bầu dục. Quả đậu hình tràng hạt thắt lại không đều giữa các hạt nhẵn không mở đều có mũi nhọn ngắn, hạt 2-5 hình bầu dục hơi dẹt màu đen bóng. Mùa hoa tháng 5-8, mùa quả tháng 9-11. Chứa flavonoid (rutin, quercetin). Vị đắng, tính hàn. Lương huyết chỉ huyết, thanh can tả hỏa. Chủ trị các chứng chảy máu, chảy máu cam, ho ra máu, băng huyết, đại tiểu tiện ra máu, đau đầu, chóng mặt, mắt đỏ. Dùng chống dị ứng, thấp khớp, tổn thương ngoài da do bức xạ. Trồng bằng hạt hoặc dâm cành, sau 3-4 năm bắt đầu thu hoạch.",
