    description:
      "Kim vàng (còn gọi Gai kim bóng, Trâm vàng, Hoa chuông vàng) là cây nhỏ mọc đứng thuộc họ Ô rô. Nhánh vuông không lông lá. Lá nguyên không lông, lá kèm biến thành gai thẳng nhọn. Cụm hoa bông ở ngọn, các lá bắc kết hợp cao 2cm. Cánh hoa mềm màu vàng nhạt. Mỗi bông thường có 18-20 hoa nhưng thường không nở hoa một lúc. Mỗi ngày chỉ nở hai hoa. Sau 7 ngày mới nở hết một bông hoa. Quả nang có hạt dẹt, hạt được bao bọc bởi một vỏ cứng. Khi quả chín khô, nổ tách bắn hạt ra xa. Cây kim vàng mọc hoang dại ở các tỉnh phía Nam nước ta, được nhiều nhà trồng làm cảnh hoặc trong chậu, hoặc thành hàng rào vì có gai nhọn, có người tỉa cây thành hình cầu. Gần đây nhiều người đã trồng để lấy lá dùng chữa rắn độc cắn. Toàn thân trên mặt đất chứa chủ yếu nhóm chất Iridoid glycosid (Barlerin, Acetylbarlerin, Ipolamiide), ngoài ra còn chứa nhóm chất phenylpropanoid (Verbascoside, Forsythoside B, Poliumoside). Dịch chiết Kim vàng có tác dụng hạ đường huyết, kháng viêm, giảm đau. Theo kinh nghiệm dân gian, lá tươi (20-35g) giã nát, vắt lấy nước cốt cho nạn nhân bị rắn độc cắn uống, bã dùng đắp lên nơi rắn cắn (GS. Đỗ Tất Lợi). Trong y học cổ truyền Thái Lan, loài cây này được sử dụng ngoài da với tác dụng chống viêm cho các trường hợp côn trùng cắn, herpes simplex (mụn rộp) và herpes zoster (bệnh zona).",
