      "Lô hội (còn gọi Nha đam, Tượng đảm, Hổ thiệt) là cây sống nhiều năm thuộc họ Lô hội, thân có thể hóa gỗ, phần trên mang lá tập trung thành hình hoa thị. Lá hình mũi mác dày, mọng nước, có nhiều chất nhầy nên giữ nhiều nước làm cho cây thích ứng được nơi khô hạn. Khi ra hoa thì trục hoa nhô lên ở giữa bó lá, mang chùm hoa màu vàng hoặc đỏ. Aloe ferox Mill. có thân cao từ 2-5m, lá mọc thành hoa thị dày, dài 15-50cm, rộng 10cm ở gốc, có gai ở mặt dưới lá và ở mép lá, hoa màu đỏ. Aloe vera (L.) Burm.f. có thân ngắn 30-50cm, lá chỉ có gai ở 2 mép, hoa màu vàng. Hoạt chất chính trong nhựa lô hội là anthraglycoside (chủ yếu là aloin A và aloin B) chiếm 15-30% là thành phần chính của nhựa lô hội. Lô hội ở liều nhỏ (0,05-0,1g) có tác dụng kích thích tiêu hóa, nhuận tràng. Liều cao (0,15-2g) là vị thuốc tẩy. Lô hội còn có tác dụng thông mật. Chất nhầy trong lá được dùng trị bỏng và sử dụng trong mỹ phẩm. Lô hội dùng ở nước ta (cả đông y và tây y) chủ yếu là nhập của nước ngoài.",
