      "Muồng trâu (còn gọi Muồng lác) là một cây nhỡ, cao chừng 1m hay hơn, đường kính có thể tới 10-12cm thuộc họ Đậu. Lá kép hình lông chim, dài 30-40cm, gồm 8-12 đôi lá chét hình trứng hoặc hình bầu dục hẹp tròn ở hai đầu, lá chét dài 5-13cm, rộng 2,5-7cm, to dần về phía ngọn. Cuống ngắn hơi phình to ở gốc. Gân lá hình lông chim. Mặt trên lá màu xanh đậm, mặt dưới lá màu xanh nhạt hơn, hai mặt nhẵn. Mép lá nguyên. Cụm hoa mọc thành bông nhiều hoa ở kẽ lá, dài tới 30-40cm, hoa màu vàng nâu nhạt. Quả giáp, dẹt, dài 8-16cm, rộng 15-17mm, có hai dìa suốt dọc quả. Trong quả có tới 60 hạt, hình quả trám. Cây này nguồn gốc ở Nam Mỹ, hiện nay được trồng ở khắp các nước vùng nhiệt đới. Ở Việt Nam cây này mọc hoang và được trồng ở nhiều nơi, nhiều nhất ở miền Nam, miền Trung và một số tỉnh miền Bắc (Thanh Hoá, Nghệ An, Hà Tĩnh). Còn mọc ở Lào và Campuchia. Trong lá, quả, gỗ và hạt đều chứa anthraglycosid (chrysophanol, aloe emodin). Lá có tác dụng nhuận tràng, lợi gan mật, tiêu độc, tiêu viêm, sát trùng, chỉ ngứa. Chủ trị táo bón (dùng sống), viêm gan, da vàng (dùng dược liệu đã sao khô). Dùng ngoài chữa hắc lào, viêm da thần kinh, ngứa lở. Biểu bì trên và biểu bì dưới của phần gân lá và phần phiến lá có lông che chở đơn bào ngắn, đầu nhọn, mặt dưới lá mật độ lông dày hơn. Phần phiến lá có u lồi cutin và lỗ khí ở cả hai mặt. Tinh thể calci oxalat hình lập phương nằm trong những tế bào mô mềm ven theo cung mô cứng.",
