    description:
      "Náng hoa trắng (còn gọi Đại tướng quân, Tỏi lơi, Náng) là cây thảo lớn thuộc họ Thủy tiên, thân hành to hình cầu hoặc hình trứng thuôn, đường kính đến 10cm, thắt lại ở đầu. Lá mọc thẳng từ thân hành, hình dài, phiến dày, dài 1m hoặc hơn, rộng 5-10cm, góc có bẹ rộng, đầu nhọn, mép nguyên uốn lượn, gân song song, gân chính lối rõ ở mặt dưới, hai mặt màu lục nhạt. Cụm hoa mọc ở giữa túm lá thành tán, trên một cán mập, dẹt, dài 40-60cm, gồm nhiều hoa to màu trắng, thơm, bao hoa có ống hẹp màu lục dài 7-10cm, mẫu 3. Lá đài và cánh hoa giống nhau, hình dài thuôn hẹp; nhị 6, chỉ nhị màu đỏ tía; bầu dạng thoi. Quả nang, gần hình cầu, đường kính 3-5cm, thường chỉ chứa 1 hạt. Mùa hoa quả: tháng 6-8. Ở Việt Nam, náng hoa trắng mọc hoang dại ở chân núi đá vôi hoặc các bãi hoang thuộc vùng ven biển, do có hoa đẹp và thơm nên được trồng làm cảnh. Náng hoa trắng là cây ưa ẩm, ưa sáng, và có thể hơi chịu nóng, sinh trưởng mạnh trong mùa mưa ẩm; một năm có thể ra 4-6 lá mới, thay thế các lá già đã xuất hiện trước đó từ 1 đến 1,5 năm. Về mùa đông, cây ngừng sinh trưởng. Cây ra hoa quả hàng năm. Tỷ lệ hoa đậu quả chỉ khoảng 40-50%. Cây có khả năng đẻ nhánh khỏe từ chồi gốc. Toàn cây và nhất là hành (bulbus) chứa nhiều alkaloid (lycorin, crinamin). Náng hoa trắng được dùng ngoài để trị các vết tụ máu do chấn thương gây đau đớn, sai gân, bong gân do té ngã, khớp xương sưng đau, hoặc xoa bóp khi bị tê thấp, nhức mỏi chân tay, cơ nhục. Các nghiên cứu gần đây cho thấy náng hoa trắng còn có tác dụng làm giảm kích thước khối phì đại tuyến tiền liệt. Bột lá màu nâu sáng, không mùi, vị hơi đắng. Chứa rất nhiều tinh thể calci oxalat hình kim, hai đầu nhọn, dài khoảng 100-110µm, đường kính khoảng 2-3µm, đơn lẻ hoặc tụ lại thành bó.",
