    description:
      "Ngải cứu (còn gọi Thuốc cứu, Ngải diệp) là cây thảo đa niên thuộc họ Cúc, cao 50-60cm, thân có rãnh dọc và lông mịn. Lá mọc cách, có nhiều dạng: lá trên ngọn nguyên hình mác; lá phía dưới xẻ một hoặc hai lần hình lông chim, phiến lá rộng xẻ 5 thùy, 2-3 lần, mặt trên nhẵn màu lục sẫm, mặt dưới màu trắng tro do có nhiều lông trắng mịn. Hoa mọc thành chùm kép gồm nhiều cụm hoa đầu; mang hoa cái hoặc hoa lưỡng tính, thường là hoa cái; hoa cái tràng hình ống, cụt hoặc có răng cưa ở đầu, hoa lưỡng tính tràng hình phễu, 5 thùy, uốn cong ra phía ngoài; nhị 5. Quả bế, thuôn nhỏ. Mùa hoa quả vào tháng 10-12. Ngải cứu mọc hoang nhiều nơi ở Việt Nam, còn thấy mọc ở nhiều nước khác ở Châu Á, cả Châu Âu nữa. Ngọn thân phơi hoặc sấy khô thu hái khi cây có hoa, dùng tươi hoặc phơi âm can hay sấy nhẹ tới khô. Cây chứa tinh dầu (cineol, borneol, thymol), flavonoid, tanin, acid amin (adenin, cholin). Ngải cứu có tác dụng ôn kinh chỉ huyết, điều kinh, an thai, trợ tiêu hóa, chỉ đau. Chủ trị kinh nguyệt không đều, băng huyết, rong huyết, thổ huyết, khí hư bạch đới, động thai, viêm ruột, lỵ. Còn dùng làm thuốc trợ tiêu hóa chữa đau bụng, nôn mửa, làm thuốc cứu trong châm cứu. Dùng ngoài chườm nóng trị đau do chấn thương. Biểu bì mang 2 loại lông che chở đa bào: lông đa bào một dãy và lông đa bào hình chữ T (đầu lông có 1 tế bào hình thoi nằm ngang, chân lông đa bào đính vào giữa tế bào hình thoi). Có lông tiết với đầu có một tế bào, chân có 3 tế bào. Chứa sợi mô cứng hình trái xoan thành dày, khoang rộng, có ống trao đổi rõ.",
