      "Nhàu (còn gọi Nhàu núi, Cây ngao, Cây mặt quỷ) là cây nhỡ cao 6-8m thuộc họ Cà phê, thân nhẵn, có nhiều cành. Lá xanh bóng loáng, mọc đối hình bầu dục dài 12-30cm, rộng 6-15cm, mép lá uốn lượn, cuống lá dài 0,5-1,2cm; lá kèm to 0,8-1,3cm. Cụm hoa mọc ở kẽ lá hoặc đối diện với lá thành đầu tròn hoặc dài 2-4cm, hoa màu trắng kết thành khối và dính nhau bởi đài; tràng có ống dài 0,7-1,2cm, có lông ở họng, 5 cánh hình mác, nhị 5, chỉ nhị ngắn, có lông, bầu 2 ô. Quả tụ do nhiều quả đơn dính sát nhau tạo thành. Quả có hình bầu dục hơi thuôn dài, kích thước dài 4-8cm, rộng 2,5-5cm; cuống dài khoảng 0,5-1cm, dễ rụng khi chín. Quả già màu xanh lục, thể chất cứng chắc, mặt ngoài sần sùi có nhiều mắt hình đa giác, mỗi 'mắt' là một quả đơn gồm có lớp cơm mềm bao quanh một hạt hình trứng. Khi chín, quả có màu trắng hoặc vàng nhạt, thể chất mềm, dễ rã ra, mùi khai. Hạt hình trứng, dài khoảng 0,5-1cm, vỏ ngoài màu nâu bóng, nhân hạt màu trắng, có chứa nhiều dầu béo. Thấy nhiều ở miền Nam Việt Nam, chưa thấy ở miền Bắc. Trong rễ, quả, lá đều chứa anthraglycosid thuộc nhóm phẩm nhuộm (morindin, damnacanthal, alizarin). Ngoài ra, Nhàu còn chứa các acid hữu cơ (acid caproic, acid caprylic), alkaloid (xeronine) và các hợp chất khác. Quả có tác dụng nhuận tràng, lợi tiểu, điều kinh, hoạt huyết. Chủ trị táo bón, tiểu tiện không thông, điều kinh, hạ sốt, chữa ho, hen; còn dùng với tính chất tăng cường miễn dịch, tăng sức đề kháng cho cơ thể. Rễ có tác dụng trừ phong thấp, nhuận tràng, bình can giáng nghịch. Chủ trị đau nhức xương khớp, huyết áp cao, phụ nữ sau khi sinh yếu mệt; còn dùng với tính chất tăng cường miễn dịch, tăng sức đề kháng cho cơ thể. Biểu bì quả có mang lỗ khí, mô mềm chứa tinh thể calci oxalat hình kim tụ thành bó. Hạt chứa rất nhiều giọt dầu béo trong phôi nhũ.",
