    description:
      "Sả (còn gọi Cỏ sả, lá sả, hương mao, sả chanh) là loài cỏ sống lâu năm thuộc họ Lúa, mọc thành bụi, rễ chùm, cao từ 0,8-1,5m hay hơn. Thân rễ trắng hay hơi tím, có đốt ngắn được bao bọc kín bởi các bẹ lá, tạo thành các tép sả. Lá hẹp như lá lúa, có gân chính nổi rõ, hai mặt và mép lá có lông cứng, nhám. Độ dài của lá tuỳ theo từng loài, có thể từ 0,2-1,2m. Cụm hoa chuỳ gồm nhiều bông nhỏ không cuống, có 2 loại hoa trên cùng một cây: hoa lưỡng tính và hoa đực. Toàn cây có mùi thơm đặc biệt. Cây sả được trồng khắp nơi trên Việt Nam, thường dùng làm gia vị và chiết tinh dầu. Tinh dầu có thành phần chính là citral A (geranial) và citral B (neral), myrcen và các thành phần khác (nerol, geraniol, citronellal, terpinolen, geranyl acetat, và methylheptenon) thay đổi tuỳ từng loại sả. Mùi đặc trưng của sả do thành phần methylheptenon có trong tinh dầu. Ngoài ra còn chứa flavonoid (luteolin, isoorientin 2'-O-rhamnoside, quercetin, kaempferol và apiginin). Lá sả dùng pha nước uống cho mát và trị đầy bụng; củ sả có tác dụng thông tiểu tiện, làm ra mồ hôi, chữa cảm sốt; tinh dầu Sả dùng làm thuốc trợ tiêu hóa, xông chữa cảm sốt, khử mùi hôi tanh và xua đuổi ruồi, muỗi. Bên cạnh loài Sả chanh, còn có Sả Citronelle (Cymbopogon winterianus - Sả Java, Cymbopogon nardus - Sả Srilanka), Sả hoa hồng/Palmarosa (Cymbopogon martini), và Sả chanh Lemongrass khác (Cymbopogon flexuosus).",
