    origin: "Việt Nam (mọc hoang và trồng trọt khắp nơi)",
    description:
      "Sen (còn gọi Liên) là cây thủy sinh thuộc họ Sen, sống lâu năm, mọc dưới nước. Thân rễ hình trụ mọc trong bùn gọi là ngó sen hay ngẫu tiết, ăn được. Lá mọc lên khỏi mặt nước, cuống lá dài có gai nhỏ, phiến lá hình khiên to đường kính 60-70cm có gân toả tròn. Hoa to màu trắng hay đỏ hồng, đều lưỡng tính. Đài 3-5 màu lục, tràng gồm nhiều cánh màu hồng hay trắng. Nhị nhiều, bao phấn 2 ô. Trung đới mọc dài ra thành phần hình trắng gọi là gạo sen dùng để ướp chè. Nhiều lá noãn đựng trong đế hoa loe ra hình nón ngược gọi là gương sen hay liên phòng. Quả chứa hạt gọi là liên nhục. Hạt hình trái xoan dài 1,1-1,3cm, đường kính 0,9-1,1cm, mặt ngoài có màng mỏng màu nâu với nhiều đường vân dọc. Bóc màng ngoài để lộ hai lá mầm bằng nhau màu trắng ngà chứa nhiều tinh bột. Chồi mầm còn gọi là liên tâm (tâm sen) dài khoảng 1cm rộng 0,1cm, phần trên là chồi mầm màu lục sẫm gồm 4 lá non, phần dưới là rễ và thân mầm hình trụ màu vàng nhạt. Biểu bì lá trên gồm một lớp tế bào hình chữ nhật nhỏ, mặt ngoài có núm lồi. Biểu bì dưới có tầng cutin dày. Xen kẽ giữa tế bào mô mềm có nhiều khuyết to, xung quanh mỗi khuyết có nhiều tinh thể calci oxalat hình cầu gai. Bột tâm sen màu lục sẫm vị đắng. Bột lá có tinh thể calci oxalat hình cầu gai đường kính 25-36µm. Bột hạt có nhiều hạt tinh bột hình trứng hoặc tròn. Hạt sen dùng làm thực phẩm bổ dưỡng, chữa suy nhược thần kinh, mất ngủ. Tâm sen trị mất ngủ, di tinh, thổ huyết. Lá sen trị say nắng, tiêu chảy, các loại chảy máu. Ngó sen cầm máu, trị tiêu chảy.",
