    description:
      "Tam thất nam (còn gọi Tam thất gừng, Khương tam thất) là cây thảo thuộc họ Gừng, không có thân, có thân rễ dày bao bởi vết lá rụng, thường phân nhánh mang nhiều củ nhỏ bằng quả trứng chim xếp thành chuỗi, có rễ con dạng sợi. Lá mọc rời 3-5 cái, có cuống dài, xuất hiện sau khi cây ra hoa. Phiến lá thuôn dài, chóp nhọn, màu lục, lục pha nâu hay nâu tím, mép nguyên lượn sóng. Cụm hoa ở gốc nằm bên lá, cuống hoa dài 6-8cm, ở phía cuối có một lá bắc hình ống bao lấy hoa. Hoa 4-5 cái, có lá bắc và lá bắc con dạng màng. Tràng hoa màu trắng, họng vàng. Bầu nhẵn chia 3 ô. Cây mọc hoang ở chỗ ẩm mát, ven bờ suối, hốc khe. Thường được trồng lấy củ làm thuốc. Mặt ngoài của củ có vằn ngang màu đen, trong có chất bột trắng ngà như màu của củ Tam thất. Thân rễ chứa tinh dầu gồm các sesquiterpen như α-copaene (32.2%) và (-)-allo-aromadendren (11.3%) cùng monoterpen, tinh bột. Trong lá cũng chứa tinh dầu nhưng với hàm lượng ít hơn. Tam thất nam có vị cay, hơi đắng, tính ấm, có tác dụng thông kinh hoạt huyết, tiêu viêm, cầm máu. Thường được dùng chữa hành kinh chậm kỳ, máu xấu lởn vởn không tươi, đau bụng khi hành kinh, thổ huyết, chảy máu cam, kinh nguyệt quá nhiều, trùng độc cắn và rắn cắn, đau sưng do ngã, đau xương do phong thấp, ăn kém tiêu, nôn đầy. Cũng có khi được dùng làm thuốc bổ chữa thiếu máu. Liều dùng 4-8g dưới dạng bột. Củ có vằn ngang màu đen đặc trưng, phân biệt với các loại củ khác trong họ Gừng.",
