      "Thầu dầu (còn gọi Đu đủ tía) là cây sống lâu năm thuộc họ Thầu dầu, thân yếu nhưng có thể cao tới 10-12m. Lá mọc so le có cuống dài, 2 lá kèm hai bên họp thành một túi màng sớm rụng, phiến lá hình chân vịt gồm 5-7-9 có khi tới 11 thùy cắt sâu, mép có răng cưa không đều. Hoa mọc thành chùm xim nhiều hoa, xim dưới gồm toàn hoa đực, xim trên toàn hoa cái. Quả 3 mảnh vỏ dài 2-3cm, rộng 2cm, trên mặt có nhiều gai mềm, đầu tròn và có 3 vết lõm chia 3 ngăn, trên lưng mỗi ngăn có 1 rãnh nông. Hạt hình trứng hơi dẹt, dài 8mm, rộng 6mm, ở đầu có móng (áo hạt của noãn khổng). Mặt hạt nhẵn bóng màu nâu xám có vân đỏ nâu hay đen. Mọc hoang và được trồng ở nhiều nơi vùng nhiệt đới: Việt Nam (Hà Giang, Bắc Ninh, Vĩnh Phúc, Phú Thọ), Ấn Độ, Bắc Châu Phi, Brazil. Hạt có dầu béo 45-50% với các acid béo đặc trưng là acid ricinoleic, isoricinoleic, alkaloid (ricinin) và một protein rất độc là ricin. Lá có alkaloid (ricinin, N-demethylricinin), flavonoid (dẫn chất của kaempferon, quercetin, epicatechin), acid gallic, acid ellagic. Dầu hạt có tác dụng nhuận trường, giữ ẩm. Lá chữa đau dạ con, sót nhau (dùng ngoài). CHÚ Ý QUAN TRỌNG: Protein độc ricin trong hạt Thầu dầu CỰC KỲ NGUY HIỂM, có thể gây chết người nếu ăn khoảng 10 hạt (bỏ vỏ hạt hoặc nhai). Tuy nhiên, dầu thầu dầu điều chế bằng phương pháp ép nguội thì không độc và an toàn khi sử dụng đúng liều lượng. TUYỆT ĐỐI KHÔNG tự ý sử dụng hạt thầu dầu.",
