    description:
      "Thiên môn đông (còn gọi Dây tóc tiên) là dây leo thuộc họ Thiên môn, sống lâu năm. Dưới đất có rất nhiều rễ củ hình thoi mẫm. Thân mang nhiều cành 3 cạnh, dài nhọn, biến đổi, trông như lá. Thân mang nhiều cành hình trụ mọc xoắn vào nhau nhẵn và có gai cong nhọn, những cành nhỏ biến đổi thành lá gọi là diệp chi hình lưỡi liềm, có mặt cắt 3 góc, dài 2-3cm, đầu nhọn. Lá rất nhỏ trông như vẩy. Mùa hạ ở kẽ lá mọc hoa trắng nhỏ. Quả là một quả mọng màu đỏ khi chín. Cây mọc hoang và được trồng ở khắp nơi trong nước ta, có khi được trồng trong chậu để làm cảnh. Rễ củ gọi là Thiên đông. Sau khi thu hái, rễ được tẩm nước cho mềm, cạo bỏ vỏ, đồ chín, rút bỏ lõi rồi phơi hoặc sấy khô. Bột rễ màu trắng ngà, mùi đặc trưng, vị ngọt hơi đắng. Soi kính hiển vi thấy mảnh mô mềm gồm tế bào thành mỏng chứa tinh thể calci oxalat. Tinh thể calci oxalat hình kim xếp thành bó hay rải rác, dài 40-99µm. Rễ củ chứa saponin steroid (sarsasapogenin, yamogenin) và các acid amin tự do (asparagin). Ngoài ra còn có flavonoid, tinh bột, đường, chất nhầy, chất khoáng. Thiên môn đông có tác dụng thanh nhiệt, tiêu viêm, tiêu đờm, lợi tiểu, nhuận tràng. Thường dùng Thiên môn để chữa ho, viêm họng, viêm mũi, đái tháo đường (dạng thuốc sắc), chữa mụn nhọt, viêm da có mủ, rắn cắn (giã cây tươi đắp ngoài da), còn dùng để chữa táo bón (dạng thuốc sắc).",
