    description:
      "Thiên niên kiện (còn gọi Sơn thục) là cây sống lâu năm thuộc họ Ráy, có thân rễ mập màu xanh, đường kính 1-2cm. Lá mọc so le, có cuống dài 18-25cm, màu xanh mềm nhẵn, phía dưới cuống nở rộng thành bẹ màu vàng nhạt. Phiến lá hình đầu mũi tên, dài 11-15cm, rộng 7-11cm, đầu nhọn, phía dưới hình cánh tên, mép nguyên, mặt trên lá màu đậm hơn, hai mặt đều nhẵn, gân ở hai mép đều hướng về phía đỉnh lá. Cụm hoa là một bông mo màu lục nhạt, dài 4-5cm, rộng 10-15cm, mỗi khóm thường có 3-4 bông mo, cuống bông mo dài 5-15cm, bông ngắn hơn mo dài 3-4cm. Mùa ra hoa: tháng 3-4. Mùa quả: tháng 5-6. Thiên niên kiện mọc hoang rất nhiều ở các miền rừng núi Việt Nam, cây ưa những nơi ẩm ướt, cạnh suối hay dọc theo suối. Thu hái thân rễ già phơi hay sấy khô. Lớp bần màu vàng nâu. Mô mềm gồm các tế bào tròn, có thành mỏng. Từ ngoài vào trong có các đám sợi lớn thành dày, các bó libe-gỗ với nhiều dạng sắp xếp khác nhau. Trong mô mềm có các tế bào chứa tinh dầu, tế bào chứa tinh thể calci oxalat hình kim và hình cầu gai. Bột thân rễ màu vàng nâu, soi kính hiển vi thấy nhiều bó sợi, tế bào mô cứng thành hơi dày, mảnh tế bào mô mềm chứa tinh thể calci oxalat hình cầu gai hoặc các bó tinh thể hình kim, tế bào chứa tinh dầu màu vàng đậm, nhiều mảnh mạch vạch, mạch mạng, mạch xoắn, hạt tinh bột hình trái xoan. Tinh dầu 0,8-1% màu vàng nhạt, mùi thơm dễ chịu, gồm Monoterpenoid (Linalool chiếm hàm lượng lớn nhất) và Sesquiterpenoid (Cadinol, Cadinene). Ngoài ra còn có acid phenol và flavonoid (apigenin). Thiên niên kiện trừ phong thấp, cường cân cốt, chủ trị phong hàn thấp gây thắt lưng và đầu gối lạnh đau, chân co rút tê bại. Ngày dùng 4,5-9g phối hợp trong các bài thuốc hoặc ngâm rượu. Dùng ngoài: thân rễ tươi giã nát sao nóng bóp vào chỗ đau nhức, hoặc ngâm thân rễ khô với rượu xoa bóp chỗ đau nhức, tê bại và phong thấp.",
