    description:
      "Thuỷu xương bồ (còn gọi Bạch bồ, Nê xương bồ) là cây sống vùng đầm lầy thuộc họ Xương bồ, thân rễ phân nhánh nhiều, màu đỏ nhạt, có mùi thơm nồng. Lá hình gươm có một gân chính. Cụm hoa hình trụ. Hoa 6 cánh màu vàng lục nhạt. Quả mọng. Mùa hoa tháng 5-7, mùa quả tháng 6-8. Cây mọc hoang tại những miền núi phía Bắc và Trung Việt Nam, thường ở những nơi khe đá, khe suối, chỗ mát. Vi phẫu cắt ngang thân rễ có hình tròn hơi dẹt. Lớp biểu bì gồm những tế bào nhỏ thành dày hóa gồ dễ bóng ra. Phần mô mềm vỏ có nhiều khuyết, nhiều bó sợi hình tròn. Nhiều tế bào chứa tinh dầu màu vàng nhạt. Nhiều hạt tinh bột đơn hoặc kép trong tế bào mô mềm. Vòng nội bì có một lớp tế bào hình chữ nhật. Phần mô ruột có các bó libe-gỗ xếp đều đặn. Bột thân rễ màu nâu nhạt, mùi thơm đặc trưng. Soi kính hiển vi thấy nhiều hạt tinh bột đơn hoặc kép đường kính 3-5µm, mảnh mô mềm gồm nhiều tế bào thành mỏng chứa tinh bột, rải rác có mảnh mạch, sợi và tinh thể calci oxalat hình nhiều cạnh, tế bào chứa tinh dầu màu nâu nhạt. Thân rễ có chứa tinh dầu 1,5-3,5% chủ yếu là α-asaron, β-asaron, acorenon, iso-acoron, (Z)-sesquilavandulol, dehydroxy isocalamendiol, calamen, calamenon, asarylaldehyd, camphen. Ngoài ra còn có coumarin, saponin, chất đắng acorin (khi tiếp xúc với không khí bị oxy hóa chậm thành nhựa), tanin, acid béo, cholin. Thuỷu xương bồ có tác dụng thông khiếu, trục đờm, tăng trí nhớ, tán phong, khoan trung khử thấp, giải độc, sát trùng, kích thích hệ tiêu hóa. Chủ trị bệnh phong điên giản, đờm vít tắc, hôn mê, hay quên, mộng nhiều, viêm phế quản, tai điếc, đi lỵ đau bụng. Dùng ngoài trị mụn nhọt, ghẻ lở chảy nước. Chú ý: Trong Dược Điển Việt Nam V, dược liệu Xương bồ gồm Thuỷu xương bồ và Thạch xương bồ (Acorus tatarinowii Schott) cùng công năng chủ trị. Thạch xương bồ cũng thuộc họ Acoraceae thường mọc hoang dọc khe suối hoặc bám trên những vách đá ẩm ướt.",
