      "Trinh nữ hoàng cung (còn gọi Hoàng cung trinh nữ, Náng lá rộng, Tỏi lơi lá rộng) là cây thảo thuộc họ Thủy tiên, thân hành to gần hình cầu hoặc hình trứng thuôn, đường kính 8-10cm, phủ bởi vảy hình bản to dày màu trắng. Lá mọc thẳng từ thân hành, hình đài dài đến 50cm hoặc hơn, rộng 7-10cm, mép nguyên, gốc phẳng có bẹ, đầu nhọn hoặc tù, gân song song. Cụm hoa mọc thành tán trên cán dẹt dài 30-40cm. Lá bắc rộng hình thìa dài 7cm, màu lục, đầu nhọn. Hoa màu trắng pha hồng, dài 10-15cm, bao hoa gồm 6 phiến bằng nhau hàn liền 1/3 thành ống hẹp, khi nở đầu phiến quặn lại. Nhị 6, bầu hạ. Quả gần hình cầu (ít gặp). Mùa hoa quả tháng 8-9. Vi phẫu lá: Biểu bì trên và dưới gồm tế bào nhỏ hình vuông thành dày hóa cutin xếp đều thành hàng, rải rác có lỗ khí. Mô giậu không rõ. Ở phần phiến lá, mỗi gân phụ cấu tạo từ 1 bó libe-gỗ gồm 2-3 mạch gỗ cùng libe xếp thành hàng vuông góc với bề mặt biểu bì. Xen kẽ giữa các bó libe-gỗ là mô khuyết, phía trên mô khuyết thường có đám sợi. Mô mềm gồm tế bào thành mỏng kích thước không đều. Phần gân chính có cấu tạo tương tự gân phụ nhưng bó libe-gỗ to hơn ở phần lồi, sát lớp biểu bì dưới có đám mô dày. Bột lá màu nâu nhạt, mùi đặc trưng, vị hơi đắng, mảnh biểu bì mang lỗ khí và cutin lồi, nhiều mảnh mạch vòng điểm hoặc đan chéo, mạch vạch xếp thưa đặc biệt, tinh thể calci oxalat hình kim thường bị gãy đứng riêng lẻ hoặc tụ thành đám. Cây ưa ẩm, ưa sáng hoặc chịu nóng một phần, sinh trưởng phát triển tốt trong khí hậu nóng ẩm vùng nhiệt đới, sinh trưởng mạnh mùa xuân hè. Ra hoa hàng năm nhưng không đậu quả ở Việt Nam, ở Thái Lan và Ấn Độ có thể thu hạt giống. Chứa alkaloid (lycorin, crinin, crinamidin, augustamin) và flavonoid (astragalin, isoquercitrin), thân rễ chứa glucan. Chủ trị tiểu tiện bí dắt, u xơ tuyến tiền liệt, u vú, u tử cung, u dạ dày. Lá tươi và thân hành dùng ngoài hơ nóng xoa bóp vào chỗ sưng đau do thấp khớp, sang chấn.",
