    description:
      "Vông nem (còn gọi Lá vông, Hải đồng, Thích đồng) là cây cao thuộc họ Đậu, cao 10-20m, mọc khắp nơi đặc biệt ưa mọc ở ven biển, thân có gai ngắn. Lá có cuống dài gồm ba lá chét. Mỗi lá chét hình gần như ba cạnh, đầu lá thuôn nhọn, đáy vát tròn, mép lá nguyên, mặt lá nhẵn, dài 6-13cm, rộng 6-15cm. Lá chét giữa thường có chiều rộng lớn hơn chiều dài. Hoa màu đỏ tươi tụ họp từ 1-3 thành chùm dầy. Quả giáp dài 15-30cm, đen, hơi hẹp lại ở giữa các hạt, trong mỗi quả có 5-6 hạt hình thận màu đỏ hoặc nâu, tẽ rộng hình trứng đen có vành trắng. Vi phẫu gân giữa: Biểu bì trên và dưới gồm một lớp tế bào xếp đều, riêng biểu bì dưới có mang lỗ khí và lông tiết hình trứng đầu đa bào chân đơn bào rất ngắn. Sát lớp biểu bì trên và dưới có mô dày. Trong mô mềm rải rác có calci oxalat hình thoi và hình đa giác. Libe-gỗ xếp thành một vòng ở chính giữa gân lá, vòng mô cứng bao bọc bên ngoài các bó libe-gỗ. Mô mềm gồm tế bào hình tròn to thành mỏng. Vi phẫu phiến lá: Dưới biểu bì trên là mô mềm giậu gồm 2 lớp tế bào dài, dưới là mô mềm khuyết. Từng quãng có những bó libe-gỗ của gân nhỏ nối liền biểu bì trên và biểu bì dưới, cắt ngang mô mềm giậu và mô mềm khuyết. Rải rác có calci oxalat hình thoi và hình đa giác. Bột lá: Mảnh biểu bì trên gồm tế bào nhiều cạnh ngoằn ngoèo thành mỏng. Mảnh biểu bì dưới có lỗ khí kiểu hạt cà phê và lông tiết hình trứng đầu đa bào (4-6 tế bào chồng lên nhau) chân đơn bào rất ngắn. Mảnh gân lá tế bào hình chữ nhật thành mỏng có chứa calci oxalat hình thoi và hình đa giác. Mảnh mô mềm giậu, bó sợi thành hơi dày, mảnh mạch mạng, mạch xoắn. Lá và vỏ thân chứa alkaloid (erythramin, erysopin, erysonin), saponin, flavonoid, tannin. Có công năng an thần, sát trùng, chủ trị mất ngủ (uống), mụn nhọt, loét, trĩ, lậu (đắp ngoài). Ngày dùng 4-6g dạng thuốc sắc, thường phối hợp với các vị thuốc khác, dùng ngoài lượng thích hợp.",
